"""Playback and context history for motion generated by MotionBricks."""

from __future__ import annotations

import math
from dataclasses import replace

import numpy as np
import warp as wp

from motius.configuration.motionbricks_runtime import MotionBricksInferenceConfig
from motius.motion.runtime.motionbricks.animation_buffer import AnimationBuffer
from motius.motion.runtime.motionbricks.pose_utils import sample_root_position
from motius.motion.runtime.motionbricks.skeleton import Skeleton
from motius.motion.runtime.motionbricks.soma_buffers import PoseToken
from motius.pipelines.motionbricks.runtime_soma_engine import MotionBricksSOMAEngine
from motius.pipelines.motionbricks.runtime_unitree_g1_engine import (
    MotionBricksUnitreeG1Engine,
)
from motius.pipelines.motionbricks.scene_motion_recorder import MotionRecorder
from motius.pipelines.motionbricks.scene_target_pose import TargetPoseInferenceParams


class _GeneratedMotionPlayer:
    """Manage generation, playback timing, and recorded motion."""

    def __init__(self, engine, context, target, output, motion_history) -> None:
        self.engine = engine
        self.context = context
        self.target = target
        self.output = output
        self.motion_history = motion_history
        self.playback_time = 0.0
        self.transition_early_by_frames = 0
        self._generated_root_positions = np.zeros((1, 3), dtype=np.float32)

    @property
    def playback_duration(self) -> float:
        """Playback time of the transition point."""
        end_frame = max(0, self.output.num_frames - 1 - self.transition_early_by_frames)
        return end_frame / self.output.sample_rate

    @property
    def time_to_transition(self) -> float:
        """Seconds until the transition point. Sampling can continue past it."""
        return max(0.0, self.playback_duration - self.playback_time)

    def generate(
        self,
        target_poses: wp.array,
        inference_params: TargetPoseInferenceParams,
        *,
        config: MotionBricksInferenceConfig | None = None,
    ) -> None:
        """Generate toward a target from the recorded history, then restart playback.

        Args:
            target_poses: The target's poses. Local joint transforms for SOMA, or joint
                coordinates for G1.
            inference_params: Generation settings of the target. Its num_poses_to_use
                sets how many target poses inform the model. Its
                transition_early_by_frames sets the transition point. Its
                allowed_token_counts, when set, replaces the counts in config.
            config: Other generation settings. None uses the defaults.
        """
        generation_config = (
            config if config is not None else MotionBricksInferenceConfig()
        )
        if inference_params.allowed_token_counts is not None:
            generation_config = replace(
                generation_config,
                allowed_token_counts=inference_params.allowed_token_counts,
            )
        self.target.update_from_poses(
            target_poses[: inference_params.num_poses_to_use], stream=self.engine.stream
        )
        self.transition_early_by_frames = inference_params.transition_early_by_frames
        self.refresh_context()
        self.engine.generate_animation(
            self.context, self.target, self.output, config=generation_config
        )
        self.playback_time = 0.0
        self._generated_root_positions = self.output.root_transforms()[:, :3]

    def sample(
        self,
        delta_time: float,
        destination_pose: wp.array,
        destination_foot_contacts: wp.array,
    ) -> None:
        """Advance playback, then write the pose and its foot contacts.

        Args:
            delta_time: Time to advance, in seconds. It must be finite and non-negative.
            destination_pose: Array that receives the pose at the new playback time.
            destination_foot_contacts: Array that receives the four foot contacts at that
                time.
        """
        if not math.isfinite(delta_time) or delta_time < 0.0:
            raise ValueError("delta_time must be finite and non-negative.")
        self.playback_time += delta_time
        self.output.sample(
            self.playback_time, destination_pose, stream=self.engine.stream
        )
        self.output.sample_foot_contacts(
            self.playback_time, destination_foot_contacts, stream=self.engine.stream
        )

    def record_pose(self, delta_time: float, pose: wp.array) -> None:
        """Record an evaluated character pose for the next generation context.

        Args:
            delta_time: Time since the previous recorded pose, in seconds. It must be
                finite and positive.
            pose: The character's pose. Local joint transforms for SOMA, or joint
                coordinates for G1.
        """
        self.motion_history.record(delta_time, pose, stream=self.engine.stream)

    def seed_history_from_pose(self, pose: wp.array) -> None:
        """Fill every history slot and the context with one pose.

        Args:
            pose: Local joint transforms for SOMA, or joint coordinates for G1.
        """
        self.motion_history.fill(pose, stream=self.engine.stream)
        self.refresh_context()

    def refresh_context(self) -> None:
        """Update context poses from the recorded playback history."""
        self.context.update_from_recorder(
            self.motion_history, stream=self.engine.stream
        )

    def current_root_position(self) -> np.ndarray:
        """Interpolate the generated root position at the playback time."""
        return sample_root_position(
            self._generated_root_positions, self.playback_time, self.output.sample_rate
        )


class GeneratedMotionPlayer(_GeneratedMotionPlayer):
    """Play SOMA motion generated from recorded poses and targets."""

    context: PoseToken
    target: PoseToken
    output: AnimationBuffer

    def __init__(
        self,
        engine: MotionBricksSOMAEngine,
        skeleton: Skeleton,
        *,
        history_capacity: int = 32,
    ) -> None:
        """Create the context token, target token, output buffer, and motion history.

        Args:
            engine: SOMA engine that generates the motion. Playback and recording use
                its stream.
            skeleton: Skeleton of the generated motion. Its reference pose fills the
                history until poses are recorded.
            history_capacity: Number of recent poses kept for the context.
        """
        super().__init__(
            engine,
            engine.create_input(skeleton),
            engine.create_input(skeleton),
            engine.create_output(skeleton),
            MotionRecorder(
                skeleton.reference_local_transforms,
                capacity=history_capacity,
                stream=engine.stream,
            ),
        )


class GeneratedDOFMotionPlayer(_GeneratedMotionPlayer):
    """Play G1 motion generated from recorded poses and targets."""

    def __init__(
        self,
        engine: MotionBricksUnitreeG1Engine,
        reference_joint_q: wp.array,
        *,
        history_capacity: int = 32,
    ):
        """Create the context token, target token, output buffer, and motion history.

        Args:
            engine: G1 engine that generates the motion. Playback and recording use its
                stream.
            reference_joint_q: Joint coordinates of the reference pose. They fill the
                history until poses are recorded.
            history_capacity: Number of recent poses kept for the context.
        """
        super().__init__(
            engine,
            engine.create_input(),
            engine.create_input(),
            engine.create_output(),
            MotionRecorder(
                reference_joint_q, capacity=history_capacity, stream=engine.stream
            ),
        )


__all__ = ["GeneratedDOFMotionPlayer", "GeneratedMotionPlayer"]
